import {
  AfterViewInit,
  Directive,
  DoCheck,
  ElementRef,
  EventEmitter,
  Injector,
  Input,
  OnInit,
  Output,
  Renderer2,
  forwardRef,
  inject,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormGroupDirective,
  NG_VALUE_ACCESSOR,
  NgControl,
  NgForm,
} from '@angular/forms';
import { ErrorState, voidFn } from '@questrade/allspark-angular-components/core/utils';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';

@Directive({
  selector: 'input[qInput][qAutocompleteInput]',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QAutocompleteInputDirective),
      multi: true,
    },
    { provide: FormFieldControl, useExisting: QAutocompleteInputDirective },
  ],
})
export class QAutocompleteInputDirective<T>
  extends ErrorState
  implements OnInit, AfterViewInit, DoCheck, ControlValueAccessor, FormFieldControl
{
  @Output() readonly valueChange = new EventEmitter<T | null>();

  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();
  @Input() value: T | null = null;

  controlId = '';

  private _onChange: (value: T | null) => void = voidFn;
  private _onTouch: () => void = voidFn;
  private readonly _renderer = inject(Renderer2);
  private readonly _input: ElementRef<HTMLInputElement> = inject(ElementRef);
  private _injector = inject<Injector>(Injector);

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));
  }

  ngOnInit(): void {
    this._setComponentControl();
  }

  ngAfterViewInit(): void {
    this.controlId = this._input.nativeElement.getAttribute('id') || '';
  }

  ngDoCheck(): void {
    if (this.ngControl) {
      this._updateErrorState();
    }
  }

  /** @hidden */
  writeValue(value: T | null): void {
    this._onChange(value);
    this.value = value;
    this.valueChange.emit(this.value);
  }

  /** @hidden */
  registerOnChange(fn: (_: T | null) => void): void {
    this._onChange = fn;
  }

  /** @hidden */
  registerOnTouched(fn: () => void): void {
    this._onTouch = fn;
  }

  /** @hidden */
  setDisabledState(isDisabled: boolean): void {
    this._renderer.setProperty(this._input.nativeElement, 'disabled', isDisabled);
  }

  _searchTermChanged(): void {
    this._onTouch();
  }

  private _setComponentControl(): void {
    const injectedControl = this._injector.get(NgControl, null);

    if (injectedControl) {
      this.ngControl = injectedControl;
    }
  }
}
