import { hasModifierKey } from '@angular/cdk/keycodes';
import { CommonModule } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChild,
  ElementRef,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  OnInit,
  Output,
  Renderer2,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
  booleanAttribute,
  inject,
  numberAttribute,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import {
  DOWN_ARROW,
  ENTER,
  SPACE,
  UP_ARROW,
  nGramScore,
} from '@questrade/allspark-angular-components/core/utils';
import {
  QDropmenuComponent,
  QDropmenuDensity,
  QDropmenuLoadingVariant,
  QDropmenuOption,
  QDropmenuOriginDirective,
} from '@questrade/allspark-angular-components/dropmenu';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import {
  QInputDirective,
  QInputGroupComponent,
} from '@questrade/allspark-angular-components/input';
import { cancelOutline, locationOutline, search } from '@questrade/allspark-icons/icons';
import { BehaviorSubject, Observable, debounceTime, delay, fromEvent, takeUntil } from 'rxjs';
import { QAutocompleteInputDirective } from './autocomplete-input.directive';
import { QAutocompleteDropmenuWidth } from './types/autocomplete-dropmenu-width.type';
import { QAutocompleteVariant } from './types/autocomplete-variant.type';

@Component({
  imports: [
    CommonModule,
    QInputGroupComponent,
    QIconComponent,
    QDropmenuComponent,
    QDropmenuOriginDirective,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-autocomplete',
  templateUrl: './autocomplete.component.html',
  styleUrls: ['./autocomplete.component.scss'],
  providers: [QDestroyService],
})
export class QAutocompleteComponent<T> implements OnInit, AfterViewInit {
  @Output() readonly valueChange = new EventEmitter<QDropmenuOption<T>>();
  @Output() readonly dropmenuOpened = new EventEmitter<void>();
  @Output() readonly dropmenuClosed = new EventEmitter<void>();

  @Input() dropmenuWidth: QAutocompleteDropmenuWidth = 'full';
  @Input() dropmenuDensity: QDropmenuDensity = 'default';
  @Input() variant: QAutocompleteVariant = 'search';
  @Input({ transform: numberAttribute }) dropmenuMinWidth = 0;
  @Input({ transform: numberAttribute }) dropmenuMinHeight = 0;
  /**
   * @deprecated Use `dropmenuOffset` instead.
   * @breaking-change First major after 16 Apr 2026
   */
  @Input({ transform: numberAttribute }) dropmenuOffsetY = 4;
  @Input({ transform: numberAttribute }) dropmenuOffset = 4;
  @Input({ transform: booleanAttribute }) customSearch = false;
  @Input({ transform: booleanAttribute }) searchCaseSensitive = false;
  @Input({ transform: numberAttribute }) searchResultsSize = 10;
  @Input({ transform: numberAttribute }) searchDebounce = 0;
  @Input({ transform: numberAttribute }) searchGramSize = 2;
  @Input({ transform: booleanAttribute }) loading = false;
  @Input() footerMessage = '';
  @Input() inputValueFormatter: ((option: QDropmenuOption<T>) => string) | null = null;
  @Input() emptyStateTemplate: TemplateRef<unknown> | null = null;
  @Input() optionTemplate: TemplateRef<unknown> | null = null;
  @Input() footerTemplate: TemplateRef<unknown> | null = null;
  @Input() loadingVariant: QDropmenuLoadingVariant = 'spinner';
  @Input() loadingSkeletonTemplate: TemplateRef<unknown> | null = null;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-autocomplete';

  @Input() get options(): QDropmenuOption<T>[] {
    return this._filteredOptions ?? this._options;
  }
  set options(value: QDropmenuOption<T>[]) {
    this._options = value;
    this._selectedOption = this._findSelectedOption();
  }

  @ContentChild(QInputDirective, { read: ElementRef }) _input!: ElementRef<HTMLInputElement>;
  @ContentChild(QAutocompleteInputDirective) _autocompleteInput!: QAutocompleteInputDirective<T>;

  @ViewChild('dropmenu', { static: true }) _dropMenu!: QDropmenuComponent<T>;
  @ViewChild('clearIconRef', { read: ElementRef }) _clearIcon!: ElementRef<HTMLElement>;

  @HostBinding('class') _rootClass = 'q-autocomplete';

  @HostListener('document:click') _clickedOutside(): void {
    if (this._isOpened) {
      this._dropMenu.close();
    }
  }

  _value: T | null = null;
  _selectedOption: QDropmenuOption<T> | null = null;
  _searchStringObservable: Observable<string> | null = null;
  _inputHasFocus = false;
  _clearIconCanHaveFocus = false;

  private _searchString$ = new BehaviorSubject('');
  private _options: QDropmenuOption<T>[] = [];
  private _filteredOptions: QDropmenuOption<T>[] | null = null;
  private _inputHasAriaExpanded = false;
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _changeDetectorRef = inject(ChangeDetectorRef);
  private readonly _renderer = inject(Renderer2);

  ngOnInit(): void {
    this._iconRegistry.registerIcons([search, cancelOutline, locationOutline]);

    this._searchString$
      .pipe(debounceTime(this.searchDebounce), takeUntil(this._destroy$))
      .subscribe(this._search.bind(this));

    this._searchStringObservable = this._searchString$.asObservable();

    this._dropMenu._withTypeahead = false;
    this._dropMenu._selectKeys = [ENTER];
  }

  ngAfterViewInit(): void {
    if (!this._input) return;

    this._bindAriaAttributes();

    this._setInputChangeEvent();
    this._setInputClickEvent();
    this._setInputFocusEvent();
    this._setInputBlurEvent();
    this._setInputKeydownEvent();
    this._setClearIconBlurEvent();

    this._monitorInputAutocompleteValueChanges();
    this._value = this._autocompleteInput?.value;
    this._updateInputValue();
  }

  _clear(): void {
    if (this._input) {
      this._dropMenu.close();
      this._clearPreviousValue();
      this._autocompleteInput?._searchTermChanged();
      this._input.nativeElement.focus();
    }
  }

  _onClearIconKeydown(event: KeyboardEvent): void {
    if (!hasModifierKey(event) && [SPACE, ENTER].includes(event.code)) {
      event.preventDefault();
      this._clear();
    }
  }

  _onDropmenuOpened(): void {
    this._toggleAriaExpanded('true');
    this.dropmenuOpened.emit();
  }

  _onDropmenuClosed(): void {
    this._clearIconCanHaveFocus = false;
    this._toggleAriaExpanded('false');
    this.dropmenuClosed.emit();
  }

  _onValueChange(event: QDropmenuOption<T> | QDropmenuOption<T>[]): void {
    this._value = (event as QDropmenuOption<T>)?.value;
    this._selectedOption = this._findSelectedOption();
    this._autocompleteInput?.writeValue(this._value);
    this.valueChange.emit(event as QDropmenuOption<T>);
  }

  _preventDropmenuClose(event: MouseEvent | KeyboardEvent): void {
    if (this._isOpened) {
      event.stopPropagation();
      return;
    }
    this._input?.nativeElement?.focus();
  }

  get _isOpened(): boolean {
    return this._dropMenu?.isOpened;
  }

  get _showClearIcon(): boolean {
    if (!this._input) {
      return false;
    }

    if (this._input.nativeElement.disabled || !this._input.nativeElement.value) {
      return false;
    }

    return this._inputHasFocus || this._clearIconCanHaveFocus || this._isOpened;
  }

  private _bindAriaAttributes(): void {
    const inputHasAriaAutoComplete = this._input.nativeElement.hasAttribute('aria-autocomplete');
    if (!inputHasAriaAutoComplete) {
      this._renderer.setAttribute(this._input.nativeElement, 'aria-autocomplete', 'list');
    }

    this._inputHasAriaExpanded = this._input?.nativeElement.hasAttribute('aria-expanded');
  }

  private _setInputChangeEvent(): void {
    fromEvent(this._input.nativeElement, 'input')
      .pipe(takeUntil(this._destroy$))
      .subscribe(() => {
        this._autocompleteInput?._searchTermChanged();
        const emptySearchTerm = !this._input.nativeElement.value;
        if (emptySearchTerm) {
          this._clearPreviousValue();
          this._toggleAriaExpanded('false');
          this._dropMenu.close();
        } else if (this.customSearch) {
          this._dropMenu.open();
        }
        this._searchString$.next(this._input.nativeElement.value);

        this._changeDetectorRef.markForCheck();
      });
  }

  private _setInputFocusEvent(): void {
    fromEvent(this._input.nativeElement, 'focus')
      .pipe(takeUntil(this._destroy$))
      .subscribe(() => {
        this._inputHasFocus = true;
        this._clearIconCanHaveFocus = true;
        this._changeDetectorRef.markForCheck();
      });
  }

  private _setInputClickEvent(): void {
    fromEvent(this._input.nativeElement, 'click')
      .pipe(takeUntil(this._destroy$), delay(0))
      .subscribe(() => {
        if (this._input.nativeElement.value) {
          this._dropMenu.open();
        }
      });
  }

  private _setInputBlurEvent(): void {
    fromEvent(this._input.nativeElement, 'blur')
      .pipe(takeUntil(this._destroy$))
      .subscribe(() => {
        this._inputHasFocus = false;
        this._changeDetectorRef.markForCheck();
      });
  }

  private _setInputKeydownEvent(): void {
    fromEvent(this._input.nativeElement, 'keydown')
      .pipe(takeUntil(this._destroy$))
      .subscribe((event: Event) => {
        if (!this._input.nativeElement.disabled) {
          this._handleInputButtonKeyDown(event as KeyboardEvent);
        }
      });
  }

  private _handleInputButtonKeyDown(event: KeyboardEvent): void {
    const handleKeyDown = (): void => {
      event.preventDefault();
      if (!this._isOpened) {
        event.stopPropagation();
        this._dropMenu.open();
      }
    };

    switch (event.code) {
      case DOWN_ARROW:
      case UP_ARROW:
      case ENTER:
        handleKeyDown();
        break;
    }
  }

  private _setClearIconBlurEvent(): void {
    fromEvent(this._clearIcon.nativeElement, 'blur')
      .pipe(takeUntil(this._destroy$))
      .subscribe(() => {
        this._clearIconCanHaveFocus = false;
        this._inputHasFocus = false;
        this._changeDetectorRef.markForCheck();
      });
  }

  private _monitorInputAutocompleteValueChanges(): void {
    this._autocompleteInput?.valueChange
      .pipe(takeUntil(this._destroy$))
      .subscribe((value: T | null) => {
        this._value = value;
        this._updateInputValue();
      });
  }

  private _toggleAriaExpanded(expanded: 'true' | 'false'): void {
    if (this._inputHasAriaExpanded) {
      return;
    }

    this._renderer.setAttribute(this._input?.nativeElement, 'aria-expanded', expanded);
  }

  private _updateInputValue(): void {
    this._selectedOption = this._findSelectedOption();
    this._renderer.setProperty(this._input.nativeElement, 'value', this._getFormattedLabel());
  }

  private _getFormattedLabel(): string {
    if (!this._selectedOption) {
      return '';
    }

    if (this.inputValueFormatter && typeof this.inputValueFormatter === 'function') {
      return this.inputValueFormatter(this._selectedOption);
    }

    const getSubLabelValue = (): string => {
      const subLabel = this._selectedOption?.subLabel ? ', ' + this._selectedOption.subLabel : '';
      return this._selectedOption?.label + subLabel;
    };

    return this.variant === 'search' ? this._selectedOption.label : getSubLabelValue();
  }

  private _findSelectedOption(): QDropmenuOption<T> | null {
    return this._options?.find((option) => option.value === this._value) ?? null;
  }

  private _clearPreviousValue(): void {
    this._autocompleteInput?.writeValue(null);
  }

  private _search(value: string): void {
    if (value === '' || this.customSearch) {
      this._filteredOptions = null;
    } else {
      this._filteredOptions = [...this._options]
        .filter(
          (option) =>
            !option.disabled &&
            nGramScore(option.label, value, this.searchCaseSensitive, this.searchGramSize) > 0,
        )
        .sort(
          (a, b) =>
            nGramScore(b.label, value, this.searchCaseSensitive, this.searchGramSize) -
            nGramScore(a.label, value, this.searchCaseSensitive, this.searchGramSize),
        )
        .slice(0, this.searchResultsSize);
      this._dropMenu.open();
    }
    this._changeDetectorRef.markForCheck();
  }
}
